import sys, time, threading, numpy as np, coremltools as ct, torch
from PIL import Image
from ultralytics import YOLO
d=sys.argv[1]
img=Image.fromarray((np.random.rand(384,640,3)*255).astype(np.uint8))
for cu in (ct.ComputeUnit.CPU_AND_NE, ct.ComputeUnit.ALL):
    m=ct.models.MLModel(f"{d}/b1.mlpackage", compute_units=cu); x={"image": img}
    for _ in range(5): m.predict(x)
    t=time.time()
    for _ in range(200): m.predict(x)
    print(f"{cu.name}: {200/(time.time()-t):.0f} fps")
