xb=torch.rand(64,3,384,640,device="mps").half()
with torch.inference_mode():
    def gpu_loop(n):
        for _ in range(n): g(xb)
        torch.mps.synchronize()
    gpu_loop(2); t=time.time(); gpu_loop(8); print(f"GPU raw: {512/(time.time()-t):.0f} fps")
    res={}
    def ane_loop():
        t=time.time(); k=0
        while time.time()-t<5: m.predict(x); k+=1
        res['ane']=k/(time.time()-t)
    th=threading.Thread(target=ane_loop); th.start(); t=time.time(); n=0
    while th.is_alive(): gpu_loop(1); n+=64
    g_fps=n/(time.time()-t); th.join()
    print(f"parallel: gpu {g_fps:.0f} + ane {res['ane']:.0f} = {g_fps+res['ane']:.0f} fps")
EOF

